mod math {
    pub fn double(n: i32) -> i32 {
        n * 2
    }

    // private: only reachable from inside this module
    fn offset() -> i32 {
        1
    }

    pub fn double_plus_one(n: i32) -> i32 {
        double(n) + offset()
    }
}

fn main() {
    println!("{}", math::double(21));
    println!("{}", crate::math::double_plus_one(20));
}

mod outer {
    pub fn tag() -> &'static str {
        "outer"
    }

    pub mod inner {
        // super:: is the parent module
        pub fn tag() -> String {
            format!("{}-inner", super::tag())
        }
    }
}

use crate::outer::inner::tag;

fn main() {
    println!("{}", tag());
    println!("{}", crate::outer::tag());
}

fn add(a: i32, b: i32) -> i32 {
    a + b
}

fn divide(a: i32, b: i32) -> i32 {
    if b == 0 {
        panic!("cannot divide by zero");
    }
    a / b
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn adds_two_numbers() {
        assert_eq!(add(2, 3), 5);
    }

    #[test]
    fn adds_a_negative_number() {
        let total = add(-4, 1);
        assert!(total < 0);
    }

    #[test]
    #[should_panic(expected = "cannot divide by zero")]
    fn dividing_by_zero_panics() {
        divide(1, 0);
    }
}

