exercise.solution:
mod math {
    pub fn double(n: i32) -> i32 {
        n * 2
    }

    fn offset() -> i32 {
        1
    }

    pub fn double_plus_one(n: i32) -> i32 {
        double(n) + offset()
    }

    pub fn triple(n: i32) -> i32 {
        n * 3
    }
}

fn main() {
    println!("{}", math::double(21));
    println!("{}", math::double_plus_one(20));
    println!("triple = {}", math::triple(7));
}
